<script lang="ts">import {auth} from '#lib/auth.svelte.ts';import {anyApi} from 'convex/server';import {untrack} from 'svelte';let retention=$state<any>(null),rows=$state<any[]>([]),cursor=$state<string|null>(null),done=$state(false),error=$state(''),busy=$state(false),confirmations=$state<Record<string,string>>({});async function load(reset=true){if(!auth.client)return;busy=true;try{retention=await auth.client.query(anyApi.maintenance.status,{});const result=await auth.client.query(anyApi.privacy.queue,{paginationOpts:{numItems:25,cursor:reset?null:cursor}});rows=reset?result.page:[...rows,...result.page];cursor=result.continueCursor;done=result.isDone;}catch(e){error=(e as Error).message;}finally{busy=false;}}$effect(()=>{if(auth.client)untrack(()=>void load());});async function approve(id:string){busy=true;error='';try{await auth.client!.mutation(anyApi.privacy.approve,{id,confirmation:confirmations[id]??''});await load();}catch(e){error=(e as Error).message;}finally{busy=false;}}</script><svelte:head><title>Privacy operations — PuntersEdge</title></svelte:head><h1 class="text-3xl font-bold">Privacy operations</h1><p class="mt-3 text-haze">Review authenticated deletion requests. Fulfilment removes personal application and authentication data in bounded batches, preserves a deactivated ledger identity, and scrubs financial contact details. Open payment reviews must be resolved first.</p>{#if error}<p role="alert" class="surface mt-4 p-4 text-loss">{error}</p>{/if}{#if retention}<div class="surface mt-5 p-4"><h2 class="font-bold">Daily bounded retention</h2><p class="mt-2 text-sm text-haze">Last run {new Date(retention.at).toLocaleString('en-NG')} · At most {retention.maximumDailyDeletes} records removed per day</p><p class="mt-2 text-book">Stale pending payments: {retention.staleCountCapped?'at least ':''}{retention.stalePending}. <a href="/admin/payments" class="underline">Review payments</a></p></div>{/if}<div class="mt-5 grid gap-4">{#each rows as row}<article class="surface p-5"><h2 class="font-bold">Requested account erasure</h2><p class="mt-2 break-all">User {row.userId}</p><p class="mt-2 text-sm text-haze">Requested {new Date(row.createdAt).toLocaleString('en-NG')}</p><label class="mt-3 block">Enter FULFIL DELETION<input class="field mt-2 w-full" bind:value={confirmations[row._id]} autocomplete="off"/></label><button class="btn-ghost mt-3 text-loss" disabled={busy||confirmations[row._id]!=='FULFIL DELETION'} onclick={()=>approve(row._id)}>Fulfil this user's deletion request</button></article>{:else}<p class="surface p-5 text-haze">{busy?'Loading requests…':'No open deletion requests.'}</p>{/each}</div>{#if !done}<button class="btn-ghost mt-4" disabled={busy} onclick={()=>load(false)}>Load more requests</button>{/if}